<script setup>
import { onMounted, reactive, ref } from 'vue'
import { conviveApi } from '../services/convive'
import { mensajeError } from '../services/api'
const gastos = ref([]); const cargando = ref(true); const error = ref(''); const mensaje = ref(''); const formulario = reactive({ concepto: '', importe: '', fecha: new Date().toISOString().slice(0, 10), categoria: 'OTROS', pagadorUsuarioId: '', participantesUsuarioIds: [] })
const categorias = ['ALQUILER', 'ALIMENTACION', 'ELECTRICIDAD', 'AGUA', 'INTERNET', 'OTROS']
async function cargar() { cargando.value = true; try { gastos.value = (await conviveApi.obtenerGastos()).data } catch (e) { error.value = mensajeError(e) } finally { cargando.value = false } }
async function crear() { error.value = ''; try { await conviveApi.crearGasto({ ...formulario, importe: Number(formulario.importe), pagadorUsuarioId: Number(formulario.pagadorUsuarioId), participantesUsuarioIds: formulario.participantesUsuarioIds.map(Number) }); mensaje.value = 'Gasto registrado.'; formulario.concepto = ''; formulario.importe = ''; await cargar() } catch (e) { error.value = mensajeError(e) } }
async function eliminar(id) { if (!confirm('¿Eliminar este gasto?')) return; try { await conviveApi.eliminarGasto(id); await cargar() } catch (e) { error.value = mensajeError(e) } }
function formatoImporte(v) { return new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' }).format(v) }
onMounted(cargar)
</script>
<template>
  <header class="mb-4"><p class="page-kicker mb-1">Economía compartida</p><h1 class="h2 mb-1">Gastos</h1><p class="text-secondary mb-0">Registra y consulta los gastos comunes de tu piso.</p></header>
  <div v-if="mensaje" class="alert alert-success">{{ mensaje }}</div><div v-if="error" class="alert alert-danger">{{ error }}</div>
  <section class="card p-4 mb-4"><h2 class="h5 mb-3">Registrar gasto</h2><form class="row g-3" @submit.prevent="crear"><div class="col-12 col-md-5"><label class="form-label">Concepto</label><input v-model="formulario.concepto" class="form-control" required maxlength="180" /></div><div class="col-6 col-md-2"><label class="form-label">Importe</label><input v-model="formulario.importe" class="form-control" type="number" min="0.01" step="0.01" required /></div><div class="col-6 col-md-2"><label class="form-label">Fecha</label><input v-model="formulario.fecha" class="form-control" type="date" required /></div><div class="col-12 col-md-3"><label class="form-label">Categoría</label><select v-model="formulario.categoria" class="form-select"><option v-for="categoria in categorias" :key="categoria">{{ categoria }}</option></select></div><div class="col-12"><label class="form-label">Pagador y participantes</label><div class="input-group"><input v-model="formulario.pagadorUsuarioId" class="form-control" placeholder="ID del pagador" required /><input v-model="formulario.participantesUsuarioIds" class="form-control" placeholder="IDs participantes separados por coma" @change="formulario.participantesUsuarioIds = String($event.target.value).split(',').map(v => v.trim()).filter(Boolean)" required /></div><div class="form-text">Usa los identificadores mostrados en la gestión del piso.</div></div><div class="col-12"><button class="btn btn-primary">Registrar gasto</button></div></form></section>
  <section class="card p-3 p-md-4"><h2 class="h5 mb-3">Historial</h2><div v-if="cargando" class="text-secondary">Cargando gastos…</div><div v-else-if="!gastos.length" class="text-center text-secondary py-4">Todavía no hay gastos registrados.</div><div v-else class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Concepto</th><th>Fecha</th><th>Categoría</th><th>Importe</th><th></th></tr></thead><tbody><tr v-for="gasto in gastos" :key="gasto.id"><td>{{ gasto.concepto }}</td><td>{{ gasto.fecha }}</td><td><span class="badge text-bg-light">{{ gasto.categoria }}</span></td><td class="fw-semibold">{{ formatoImporte(gasto.importe) }}</td><td class="text-end"><button class="btn btn-sm btn-outline-danger" @click="eliminar(gasto.id)"><i class="bi bi-trash"></i></button></td></tr></tbody></table></div></section>
</template>
